import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.StringTokenizer;import java.util.Stack;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));int n = Integer.parseInt(br.readLine().trim());long[] h = new long[n];StringTokenizer st = new StringTokenizer(br.readLine());for (int i = 0; i < n; i++) {h[i] = Long.parseLong(st.nextToken());}long[] dp = new long[n];Stack<Integer> stack = new Stack<Integer>();long maxStamina = 0;for (int i = n - 1; i >= 0; i--) {while (!stack.isEmpty() && h[stack.peek()] <= h[i]) {stack.pop();}if (stack.isEmpty()) {dp[i] = h[i];} else {dp[i] = h[i] ^ dp[stack.peek()];}stack.push(i);if (dp[i] > maxStamina) {maxStamina = dp[i];}}System.out.println(maxStamina);}}